import {account,mountAccountLink} from './account-client.js';
import {ContinuousPdfViewer} from './continuous-pdf.js?v=1';
const $=s=>document.querySelector(s);let doc=null,pdfjs=null,scale=1,token=0;
const viewer=new ContinuousPdfViewer({container:$('#book-scroll'),pagesRoot:$('#book-pages'),pageLabel:$('#book-page'),error:error=>{console.error(error);$('#book-message').textContent='部分页面暂时无法显示，可打开原文件阅读。';}});
async function openBook(unit){const n=++token,url='assets/'+unit.toLowerCase()+'.pdf';if(!$('#book-reader').open)$('#book-reader').showModal();$('#book-title').textContent=unit+' · Pure Mathematics '+unit.slice(1);$('#book-original').href=url;$('#book-message').textContent='正在载入连续页面…';scale=1;try{pdfjs??=await import('./assets/pdfjs/pdf.mjs');pdfjs.GlobalWorkerOptions.workerSrc=new URL('./assets/pdfjs/pdf.worker.mjs',import.meta.url).href;const next=await pdfjs.getDocument({url,isEvalSupported:false}).promise;if(n!==token){next.destroy();return;}doc?.destroy();doc=next;$('#book-message').textContent='';await viewer.open(doc,{zoom:scale});account.activity('book','books').catch(()=>{});}catch(error){if(n!==token)return;$('#book-message').textContent='内嵌阅读暂未载入，请点击“原文件”打开。';console.error(error);}}
async function init(){try{await account.requireUser();await mountAccountLink();document.addEventListener('click',e=>{const button=e.target.closest('[data-book]');if(button)openBook(button.dataset.book);});$('#book-close').addEventListener('click',()=>$('#book-reader').close());$('#book-prev').addEventListener('click',()=>viewer.go(viewer.current-1));$('#book-next').addEventListener('click',()=>viewer.go(viewer.current+1));$('#book-plus').addEventListener('click',()=>{scale=Math.min(2.5,scale+.2);viewer.setZoom(scale);$('#book-zoom').textContent=Math.round(scale*100)+'%';});$('#book-minus').addEventListener('click',()=>{scale=Math.max(.6,scale-.2);viewer.setZoom(scale);$('#book-zoom').textContent=scale===1?'适合宽度':Math.round(scale*100)+'%';});$('#book-full').addEventListener('click',async()=>{const el=$('#book-reader'),on=el.classList.toggle('expanded');$('#book-full').textContent=on?'退出全屏':'全屏阅读';try{if(on&&document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else if(!on&&document.fullscreenElement)await document.exitFullscreen();}catch{}viewer.resize();});$('#book-reader').addEventListener('close',()=>{token++;viewer.destroyDocument();doc?.destroy();doc=null;$('#book-reader').classList.remove('expanded');$('#book-full').textContent='全屏阅读';if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});});let resize;window.addEventListener('resize',()=>{clearTimeout(resize);resize=setTimeout(()=>viewer.resize(),150);});account.activity('visit','books').catch(()=>{});}catch(error){console.error(error);$('.books-main').innerHTML='<div class="empty"><h1>教材暂时无法载入</h1><p>请刷新页面重试。</p></div>';}}
init();
